-- =====================================================================
-- Actas de partido tomadas de la BD federativa local (Docker ffv-postgres).
-- Añade acta_fed (JSONB con la forma ActaPartido) e id_partido_fed,
-- y rellena los 67 partidos de 2026-27 (partidos y eventos_calendario) con acta/alineaciones disponibles.
-- La pestaña ACTA lee estos datos directamente, sin importar nada del portal RFEF.
-- =====================================================================

BEGIN;

ALTER TABLE partidos ADD COLUMN IF NOT EXISTS acta_fed JSONB;
ALTER TABLE partidos ADD COLUMN IF NOT EXISTS id_partido_fed INTEGER;
ALTER TABLE eventos_calendario ADD COLUMN IF NOT EXISTS acta_fed JSONB;
ALTER TABLE eventos_calendario ADD COLUMN IF NOT EXISTS id_partido_fed INTEGER;
COMMENT ON COLUMN eventos_calendario.acta_fed IS 'Acta federativa (alineaciones, cambios, goles, tarjetas) con forma ActaPartido';
COMMENT ON COLUMN eventos_calendario.id_partido_fed IS 'match_id en la BD federativa';

DROP TABLE IF EXISTS public._actas_fed;
CREATE TABLE public._actas_fed (fecha DATE, jornada TEXT, local TEXT, visitante TEXT, mid INTEGER, acta JSONB);

UPDATE partidos p
   SET acta_fed = v.acta || jsonb_build_object('competition', p.competition, 'jornada', p.jornada, 'date', to_char(p.date, 'DD/MM/YYYY')),
       id_partido_fed = v.mid
  FROM _actas_fed v
 WHERE p.date::date = v.fecha AND p.jornada = v.jornada
   AND p.local_team = v.local AND p.visitor_team = v.visitante;

UPDATE eventos_calendario e
   SET acta_fed = v.acta || jsonb_build_object('competition', e.competition, 'jornada', e.jornada,
                                               'date', to_char(e.date AT TIME ZONE 'Europe/Madrid', 'DD/MM/YYYY')),
       id_partido_fed = v.mid
  FROM _actas_fed v
 WHERE e.club_id = 'escuela-huesca' AND e.type = 'Partido'
   AND (e.date AT TIME ZONE 'Europe/Madrid')::date = v.fecha AND e.jornada = v.jornada
   AND e.local_team = v.local AND e.visitor_team = v.visitante;

DROP TABLE IF EXISTS public._actas_fed;

COMMIT;
